import fs from 'node:fs/promises';
import path from 'node:path';
import {chromium,expect} from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
const dir=path.resolve('../../work/test-runs/brohn-native-eda-ui-evidence'),report=JSON.parse(await fs.readFile(path.join(dir,'eda-event-report.json'),'utf8'));
const browser=await chromium.launch({channel:'chrome',headless:true}),context=await browser.newContext({viewport:{width:390,height:844}}),page=await context.newPage();
try{await page.goto('http://127.0.0.1:3851/');await page.getByRole('button',{name:'Data library',exact:true}).click();await page.getByLabel('Search datasets',{exact:true}).fill(report.title.replace(/ results$/,''));await page.locator(`[data-brohn-event="open_dataset"][data-brohn-value='"${report.dataset_id}"']`).click();await page.locator(`[data-brohn-event="open_report"][data-brohn-value='"${report.id}"']`).click();await page.getByRole('heading',{name:'Event support',exact:true}).waitFor();await page.getByText("Review each event's baseline and response support",{exact:true}).click();await page.waitForFunction(()=>!document.documentElement.classList.contains('shiny-busy')&&!document.querySelector('.recalculating'));
const layout=await page.evaluate(()=>({viewport:innerWidth,scrollWidth:document.documentElement.scrollWidth,elements:[...document.querySelectorAll('.brohn-main,.brohn-page,.brohn-page > *,.brohn-table,table,details')].map(e=>{const r=e.getBoundingClientRect(),s=getComputedStyle(e);return{tag:e.tagName,id:e.id,class:e.className,left:r.left,right:r.right,width:r.width,clientWidth:e.clientWidth,scrollWidth:e.scrollWidth,display:s.display,minWidth:s.minWidth,maxWidth:s.maxWidth,cssWidth:s.width,overflowX:s.overflowX,gridTemplateColumns:s.gridTemplateColumns,caption:e.querySelector('caption')?.textContent};})}));await fs.writeFile(path.join(dir,'eda-layout.json'),JSON.stringify(layout,null,2));await page.screenshot({path:path.join(dir,'eda-layout.png'),fullPage:true});const violations=(await new AxeBuilder({page}).analyze()).violations;await fs.writeFile(path.join(dir,'eda-layout-axe.json'),JSON.stringify(violations,null,2));await expect(page.locator('.shiny-output-error:visible')).toHaveCount(0);console.log(JSON.stringify({viewport:layout.viewport,scrollWidth:layout.scrollWidth,violations:violations.map(v=>v.id)}));}finally{await browser.close();}
